// ============================================================
// 字库映射表
// ============================================================

/** SRC等级单字库映射 */
export const SRC_CHAR_LIB: Record<Level, string[]> = {
  SRC100: SRC100_CHARS,
  SRC300: SRC300_CHARS,
  SRC500: SRC500_CHARS,
  SRC800: SRC800_CHARS,
};

/** SRC等级词汇库映射 */
export const SRC_WORD_LIB: Record<Level, string[]> = {
  SRC100: SRC100_WORDS,
  SRC300: SRC300_WORDS,
  SRC500: SRC500_WORDS,
  SRC800: SRC800_WORDS,
};

/** 人教版等级单字库映射 */
export const RJB_CHAR_LIB: Record<RJBLevel, string[]> = {
  RJB100: RJB100_CHARS,
  RJB300: RJB300_CHARS,
  RJB500: RJB500_CHARS,
  RJB800: RJB800_CHARS,
};

// ============================================================
// 工具函数
// ============================================================

/**
 * 获取指定等级的单字列表
 */
export function getCharList(level: Level): string[] {
  return SRC_CHAR_LIB[level] || [];
}

/**
 * 获取指定等级的词汇列表
 */
export function getWordList(level: Level): string[] {
  return SRC_WORD_LIB[level] || [];
}

/**
 * 获取指定等级的人教版单字列表
 */
export function getRJBCharList(level: RJBLevel): string[] {
  return RJB_CHAR_LIB[level] || [];
}

/**
 * 获取包含指定单字的所有词
 */
export function getWordsWithChar(char: string, level: Level): string[] {
  const words = SRC_WORD_LIB[level] || [];
  return words.filter(w => w.includes(char));
}

/**
 * 计算两个字库的交集（用于双体系交叉计算）
 */
export function getCharIntersection(charsA: string[], charsB: string[]): string[] {
  const setB = new Set(charsB);
  return charsA.filter(c => setB.has(c));
}

/**
 * 获取SRC等级对应的人教版等级
 */
export function getCorrespondingRJBLevel(level: Level): RJBLevel {
  const map: Record<Level, RJBLevel> = {
    SRC100: 'RJB100',
    SRC300: 'RJB300',
    SRC500: 'RJB500',
    SRC800: 'RJB800',
  };
  return map[level];
}

