/**
 * 获取所有题目
 */
export function getAllQuestions(): QuestionItem[] {
  return QUESTION_BANK;
}

/**
 * 按等级获取题目
 */
export function getQuestionsByLevel(level: Level): QuestionItem[] {
  return QUESTION_BANK.filter(q => q.level === level);
}
